#include <array>
#include <bit>
#include <cstdint>
#include <iostream>
#include <vector>
using U=uint16_t;struct G{int n;std::vector<U>a;};void add(G&g,int x,int y){g.a[x]|=U(1)<<y;g.a[y]|=U(1)<<x;}void rem(G&g,int x,int y){g.a[x]&=~(U(1)<<y);g.a[y]&=~(U(1)<<x);}int pc(U x){return std::popcount((unsigned)x);}bool conn(const G&g,U del){U r=((U(1)<<g.n)-1)&~del;if(!r)return true;U seen=r&-r,fr=seen;while(fr){U b=fr&-fr;fr^=b;int v=std::countr_zero((unsigned)b);U nx=g.a[v]&r&~seen;seen|=nx;fr|=nx;}return seen==r;}bool c5(const G&g){for(int v=0;v<g.n;v++)if(pc(g.a[v])<5)return false;U all=(U(1)<<g.n)-1;for(U s=0;s<=all;s++)if(pc(s)<=4&&!conn(g,s))return false;return true;}struct S{const G&g;U all;std::vector<char>co;std::vector<U>ex;std::array<U,7>b{};S(const G&x):g(x),all((U(1)<<x.n)-1),co(U(1)<<x.n),ex(U(1)<<x.n){for(U s=1;s<=all;s++){U q=s&-s;int v=std::countr_zero((unsigned)q);ex[s]=ex[s^q]|g.a[v];U seen=q,fr=q;while(fr){U z=fr&-fr;fr^=z;int w=std::countr_zero((unsigned)z);U nx=g.a[w]&s&~seen;seen|=nx;fr|=nx;}co[s]=seen==s;}}bool dfs(U r,int k,int m){if(k==7)return true;if(pc(r)<7-k)return false;U p=r&-r,rest=r^p;for(U s=rest;;s=(s-1)&rest){U q=s|p;if(co[q]){int mm=m;for(int i=0;i<k;i++)if(!(ex[q]&b[i]))mm++;if(mm<=1){b[k]=q;if(dfs(r^q,k+1,mm))return true;}}if(!s)break;}return dfs(r^p,k,m);}bool run(){return dfs(all,0,0);}};
int main(){int n=8;std::vector<std::pair<int,int>>e;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)e.push_back({i,j});int total=0,cnt5=0,neg=0;for(int a=0;a<(int)e.size();a++)for(int b=a+1;b<(int)e.size();b++)for(int c=b+1;c<(int)e.size();c++){G g{n,std::vector<U>(n)};for(auto [x,y]:e)add(g,x,y);for(int q:{a,b,c})rem(g,e[q].first,e[q].second);total++;if(!c5(g))continue;cnt5++;S s(g);if(!s.run()){neg++;std::cout<<"NEG missing "<<a<<' '<<b<<' '<<c<<'\n';}}std::cout<<"n8 exact total="<<total<<" 5conn="<<cnt5<<" negative="<<neg<<"\n";}
